@if(!$run->isFinished())<script>document.addEventListener('DOMContentLoaded',()=>{const u=@json(route('non-cadre.reporting.exports.status',$run));const t=setInterval(async()=>{const r=await fetch(u,{headers:{'Accept':'application/json'}});if(!r.ok)return;const d=await r.json();document.getElementById('status').textContent=(d.status||'').toUpperCase();document.getElementById('bar').style.width=(d.progress_percent||0)+'%';document.getElementById('message').textContent=d.failure_message||d.progress_message||'';if(d.finished){clearInterval(t);if(d.download_url)document.getElementById('action').innerHTML='<a class="btn btn-primary" href="'+d.download_url+'">Download</a>';}},1500);});</script>@endif
